func (d *DualReadDecryptor) Decrypt(ctx, ciphertext) ([]byte, error) {
  pt, err := d.active.Decrypt(ctx, ciphertext)
  if err == nil { return pt, nil }
  if !d.cfg.Enabled || !d.window.Active() { return nil, err }
  if !eligibleForFallback(err) { return nil, err }
  pt2, err2 := d.previous.Decrypt(ctx, ciphertext)
  if err2 == nil {
    d.metrics.IncFallback(reasonFrom(err))
    return pt2, nil
  }
  return nil, err
}

Notes: only one fallback attempt; previous selector is immediate predecessor only.
